FuncDef.Code:
void opRevolutionInnerRot(inout vec3 p, in float radius, in float innerRot)
{
    float a = atan(p.z, p.x);
    g_shapeLoop = a;

    p.xz *= mat2(cos(a), sin(a), -sin(a), cos(a));
    p.x -= radius;
    float a2 = PI * innerRot;

    p.xy *= mat2(cos(a2), sin(a2), -sin(a2), cos(a2));

    p.xz = vec2(length(p.xz), p.y);
}
